    N = len(S)
    num,cnt = 0,0
    mod = 2019
    rem_dict,rem_set = {},set()
    for i in range(N):
        num = (num + int(S[N-1-i]) * pow(10,i,mod)) % mod
        if num in rem_set:
            rem_dict[num] += 1
        else:
            rem_set.add(num)
