        que = deque()
        que.append((1, 1, 0))

        while que:
            row, col, count = que.popleft()
            for mr, mc in ((1, 0), (0, 1), (-1, 0), (0, -1)):
                nr, nc = row + mr, col + mc
                if grid[nr][nc] == ".":
                    que.append((nr, nc, count + 1))
                    grid[nr][nc] = "!"
                elif grid[nr][nc] == "G":
                    min_count = count + 1
                    return min_count
