import sys

MOD = 1000000007  # type: int


def solve(N: int, K: int):
    counts = [0] * (K+1)
    for i in range(K, 0, -1):
        c = pow(K//i, N, MOD)
        for j in range(i+i, K+1, i):
            c -= counts[j]
        counts[i] = c
    ans = 0
    for i, c in enumerate(counts):
        ans = (ans + (i * c) % MOD) % MOD
    print(ans)


