def event_sort(section, query):
    s_n = len(section)
    q_n = len(query)
    task = []
    for i in range(s_n):
        s, t = section[i]
        task.append((s, 0, i))
        task.append((t, 1, i))
    for i in range(q_n):
        task.append((query[i], 2, i))
    task.sort()

    se = set()

    ### この問題専用 ###
    res = [-1] * q_n # 答え
    ignore = [-1] * s_n # まだ区間が生きているか
    se_hp = [] # ignoreを元にまだ生きている区間の中でのxの最小値を求める
    heapq.heapify(se_hp)
    ##################

    for a, b, c in task:
        if b == 1:
            se.remove(c)
            ignore[c] = 1 # これは無視していい
        elif b == 0:
            se.add(c)
            heapq.heappush(se_hp, (sec[c][2], c)) # xの値をsecから引っ張る
        else:
            # 小さい順から抜け殻を捨てて回る
            while se_hp and ignore[se_hp[0][1]] == 1:
                heapq.heappop(se_hp)
            if se_hp:
                res[c] = se_hp[0][0]
            else:
                res[c] = -1
    return res

