def solve(N: int, A: "List[int]"):
    least = 0
    A.sort()
    acc = list(accumulate(A))
    for i, a in enumerate(A):
        if i == N - 1:
            print(N - least)
            break
        if A[i+1] > 2 * acc[i]:
            least = i + 1
    return


