def solve(N, A):
    B = [A[0]]
    prev = A[0]
    for a in A:
        if prev != a:
            B.append(a)
            prev = a
    count = 1
    up = False
    down = False
    for i in range(1, len(B)):
        if not up and not down:
            if B[i-1] < B[i]:
