def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(A):
    c = Counter(A)
    N = len(A)
    s = 0
    for v in c.values():
        s += v*(v-1)//2

    return N*(N-1)//2 - s + 1


