    sv=Sieve(1005)
    cnt_e=[0]*1005
    for a in range(2,II()+1):
        pe=sv.pfct(a)
        for p,e in pe:cnt_e[p]+=e
    ans=1
    for e in cnt_e:ans=ans*(e+1)%md
    print(ans)

