def COM(n,r,MOD):
    return calcNumerator(n,r,MOD) // calcDenominator(r,MOD)

def calcNumerator(n,r,MOD):
    res = 1
    for i in range(r):
        res *= n % MOD
        n -= 1
    return res

def calcDenominator(r,MOD):
    res = 1
    a = r
    for i in range(r):
        res *= a % MOD
        a -= 1
    return res

