    cnt = 0
    for i in range(D):
        if bit & (1 << i):
            point += 100*(1+i)*PC[i][0] + PC[i][1]
            cnt += PC[i][0] 

    idx = -1
    for i in range(D):
        if not bit & (1 << i):
            idx = i

    if idx == -1:
        ans.append(cnt)
    else:
        rem = max(0, G - point)
        if rem == 0:
            ans.append(cnt)
        else:
            extr_cnt = math.ceil(rem / (100*(idx+1)))
            if extr_cnt <= PC[idx][0]-1:
                ans.append(cnt+extr_cnt)


