def solve(N, region):
    dp = [ModInt(0)]*(N+1)
    dp[1] += 1
    dpsum = [ModInt(0)]*(N+1)
    dpsum[1] += 1

    for i in range(2, N+1):
        for r in region:
            left = i - r[1]
            right = i - r[0]
            if right < 0:
                continue
            left = max(left, 0)
            dp[i] += (dpsum[right] - dpsum[left-1])
        dpsum[i] = dpsum[i-1] + dp[i]

    return dp[N]


