    N = 50
    div, mod = divmod(K, N)
    ans = [i+div for i in range(N)]
    for i in range(mod):
        ans[i] += N
        for j in range(N):
            if i == j:
                continue
            ans[j] -= 1

    print(N)
    print(*ans, sep=" ")

    return


