  l_cnt = 0
  l_pre = -1
  C = [0]*(len(S))
  for i in range(1, len(S)):
    now = S[i]
    if pre == 'R' and now == 'R':
      r_cnt += 1
    elif pre == 'R' and now == 'L':
      C[i-1] = r_cnt
      r_cnt = 0
      l_pre = i
      l_cnt = 1
    elif pre == 'L' and now == 'L':
