      C[l_pre] = l_cnt
      l_cnt = 0
      r_cnt = 1
      ave = int((C[l_pre] + C[l_pre-1]) / 2)
      if (C[l_pre] + C[l_pre-1]) % 2 == 0:
        C[l_pre-1], C[l_pre] = ave, ave
      else:
        n_move = max(C[l_pre-1], C[l_pre]) - 1
