    f = [[0] * N for _ in range(N)]
    for l, r in zip(L, R):
        f[l-1][r-1] += 1
    dp = [[0] * (N + 1) for _ in range(N+1)]
    for h in range(N):
        for w in range(N):
            dp[h+1][w+1] = dp[h+1][w] + dp[h][w+1] - dp[h][w] + f[h][w]

    #print(*f, sep='\n')
