import sys

def shuffle( cards ):
	h = int( sys.stdin.readline() )
	n = len( cards )
	s = ""
	t = ""
	for i in range( h ):
		s += cards[i]
	for i in range( h, n ):
		t += cards[i]
	t += s
	return t

