def make_path(l,y1,x1,y2,x2):
    current_x = x1
    current_y = y1
    if x2 == x1:
        for i in range(y2-y1):
            l.append((current_y,current_x,current_y+1,current_x))
            current_y += 1
    elif x2 > x1:
        if y1 % 2 == 1:
            for i in range(x2-x1):
                l.append((current_y,current_x,current_y,current_x+1))
                current_x += 1
            for i in range(y2-y1):
                l.append((current_y,current_x,current_y+1,current_x))
                current_y += 1
        else:
            l.append((current_y,current_x,current_y+1,current_x))
            current_y += 1
            for i in range(x2-x1):
                l.append((current_y,current_x,current_y,current_x+1))
                current_x += 1
            for i in range(y2-y1-1):
                l.append((current_y,current_x,current_y+1,current_x))
                current_y += 1
    else:
        if y1 % 2 == 1:
            l.append((current_y,current_x,current_y+1,current_x))
