         a %= MOD
      for i in range(k):
         b *= (k-i)
         b %= MOD
      return (a*self.mod_pow(b, self.p-2)) % self.p

   def perm(self, n, k):
      if n < 0 or k < 0 or n < k:
         return 0
      if n == 0 or k == 0:
         return 1
      a = self.fact[n]
      b = self.fact[n-k]
      return (a * self.mod_pow(b, self.p-2)) % self.p

