    def f(i, h):
        if i == N:
            yield ""
            return
        for c in range(ord('a'), h):
            for s in f(i+1, h):
                yield chr(c) + s
        for s in f(i+1, h+1):
            yield chr(h) + s
    return f(0, ord('a'))


