    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N):
    M = 10**9 + 7

    def gp(n):
        prohibit = []
        for c in product('AGCT', repeat=n):
            c = ''.join(c)
            if 'AGC' in c:
                prohibit.append(c)

            for i in range(n-1):
                j = i+1
                l = list(c)
                l[i], l[j] = l[j], l[i]
                if 'AGC' in ''.join(l):
                    prohibit.append(c)
        return set(prohibit)

    p3 = gp(3)
    p4 = gp(4)



    memo = {}
    for c in product('AGCT', repeat=3):
        c = ''.join(c)
        if c not in p3:
            memo[c] = 1

    for _ in range(N-3):
        nm = Counter()
        for c in 'AGCT':
            for k, v in memo.items():
                kk = k + c
                if kk not in p4:
                    nm[kk[1:]] += v
                    nm[kk[1:]] %= M

        memo = nm


    return sum(memo.values()) % M


