def Minkowski(n, x, y, p):
    temp = 0
    for i in range(n):
        temp += abs(y[i] - x[i])**p
    return temp**(1/p)

def Chebyshev(n, x, y):
    temp = 0
    for i in range(n):
        temp = max(temp, abs(y[i] - x[i]))
    return temp

