#!/usr/bin/env python3
import sys


def solve(H: int, W: int, S: "List[str]"):
    for i in range(H):
        for j in range(W):
            if S[i][j] == "#":
                print("#", end="")
                continue
            n = 0
            if i - 1 >= 0:
                if S[i - 1][j] == "#":
                    n += 1
                if j + 1 < W and S[i - 1][j + 1] == "#":
                    n += 1
                if j - 1 >= 0 and S[i - 1][j - 1] == "#":
                    n += 1
            if i + 1 < H:
                if S[i + 1][j] == "#":
                    n += 1
                if j + 1 < W and S[i + 1][j + 1] == "#":
                    n += 1
                if j - 1 >= 0 and S[i + 1][j - 1] == "#":
                    n += 1
            if j + 1 < W and S[i][j + 1] == "#":
                n += 1
            if j - 1 >= 0 and S[i][j - 1] == "#":
                n += 1
            print(n, end="")
        print()
    return


