def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, M, X, Y):
    MOD = 10**9+7

    xs = 0
    for i in range(N):
        xs += (i-(N-(i+1)))*X[i]
        xs %= MOD
    ys = 0
    for i in range(M):
        ys += (i-(M-(i+1)))*Y[i]
        ys %= MOD
    return xs*ys % MOD


