    for i in range(N):
        if A[i] - A[mn_idx_list[i]] == max_diff:
            uf.unite(i, mn_idx_list[i])

    parents_set = set()
    for i in range(N):
        if uf.size(i) == 1:
            continue
        parents_set.add(uf.find(i))

    print(len(parents_set))

