def solve(A: int, B: int):
    A -= 1
    B -= 1
    print(-(-A // 50 + -B // 50) * 2 + 2, 100)
    while A:
        print("#" * 100)
        n = min(A, 50)
        print(".#" * n + "##" * (50 - n))
        A -= n
    print("#" * 100)
    print("." * 100)
    while B:
        n = min(B, 50)
        print(".#" * n + ".." * (50 - n))
        B -= n
        print("." * 100)


