def slv(N, A):
    b = deque()
    A.sort()
    for i in range(N//2):
        if i % 2 == 0:
            b.appendleft(A[i])
            b.append(A[N-i-1])
        else:
            b.append(A[i])
            b.appendleft(A[N-i-1])
    if N % 2 !=  0:
