def solve():
    N = Scanner.int()
    A = Scanner.map_int()
    B = Scanner.map_int()
    C = Scanner.map_int()
    A.sort()
    B.sort()
    C.sort()
    ans = 0
    for i in range(N):
        ok = -1
        ng = N
        while abs(ok - ng) > 1:
            m = (ok + ng) // 2
            if A[m] < B[i]:
                ok = m
            else:
                ng = m
        n = ok + 1
        ok = N
        ng = -1
        while abs(ok - ng) > 1:
            m = (ok + ng) // 2
            if C[m] > B[i]:
                ok = m
            else:
                ng = m
        m = N - ok
        ans += n * m
    print(ans)


